plot(t/60,m_in(:,d_idx_plot(2)),'--','LineWidth',3); %[output:4f3a96e7]
plot(t/60,m_in(:,d_idx_plot(3)),'o-','MarkerIndices',ceil((1:4*60*1/dt0:length(t))),'LineWidth',3); %[output:4f3a96e7]
legend({strcat('$d=$',sprintf("%.0f", d_vector(d_idx_plot(1))*1e6),'$\mu$m')... %[output:4f3a96e7]
        strcat('$d=$',sprintf("%.0f", d_vector(d_idx_plot(2))*1e6),'$\mu$m')... %[output:4f3a96e7]
        strcat('$d=$',sprintf("%.0f", d_vector(d_idx_plot(3))*1e6),'$\mu$m')... %[output:4f3a96e7]
        },'Interpreter','latex'); %[output:4f3a96e7]
xlabel('Time [min]','Interpreter','latex'); %[output:4f3a96e7]
ylabel('AMP: $m_\mathrm{in}$ [mM]','Interpreter','latex'); %[output:4f3a96e7]
